# owner: platform
"""Short absence notices addressed to parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.errors import ProjectError
from rosterkit.models import Mark, Student

def _check_owner(
    student: Student, marks: List[Mark]
) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id!r} does not "
                f"belong to {student.student_id!r}"
            )

def _date_text(stamp: date) -> str:
    return stamp.strftime("%B %d, %Y").replace(" 0", " ")

def _absent_days(
    student: Student, marks: List[Mark]
) -> List[date]:
    _check_owner(student, marks)
    found = days_missed(marks)
    if not found:
        raise ProjectError(
            f"no absences for {student.student_id!r}"
        )
    return found

def _body(student: Student, found: List[date]) -> str:
    count = len(found)
    unit = "day" if count == 1 else "days"
    items = (f"- {_date_text(item)}" for item in found)
    lines = "\n".join(items)
    return (
        f"{student.first_name} missed {count} {unit} "
        f"of class:\n{lines}\n"
    )

# ---
def build_absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Text for parents naming the days a student missed."""
    found = _absent_days(student, list(marks))
    name = f"{student.first_name} {student.last_name}"
    return (
        f"Dear parent or guardian of {name},\n\n"
        + _body(student, found)
    )

