# owner: platform
import unittest
from datetime import date

from rosterkit.errors import ProjectError
from rosterkit.models import Mark, Student
from rosterkit.notices import build_absence_notice

PUPIL = Student("7", "Rivera", "Ana", "A")

def mark(month_day, status="absent", owner="7"):
    return Mark(owner, date(2026, 9, month_day), status)

def notice(marks):
    return build_absence_notice(PUPIL, marks)

class NoticeTests(unittest.TestCase):
    def test_names_and_count(self):
        extra = mark(4, "present")
        text = notice([mark(10), mark(3), extra])
        self.assertIn("Ana Rivera", text)
        self.assertIn("missed 2 days", text)

    def test_dates_in_order(self):
        text = notice([mark(10), mark(3)])
        first = text.index("September 3, 2026")
        later = text.index("September 10, 2026")
        self.assertLess(first, later)

    def test_single_day_wording(self):
        self.assertIn("missed 1 day ", notice([mark(3)]))

    def test_excused_days_are_ignored(self):
        text = notice([mark(3), mark(4, "excused")])
        self.assertNotIn("September 4", text)

    def test_foreign_mark_rejected(self):
        marks = [mark(3), mark(4, owner="8")]
        with self.assertRaises(ProjectError):
            notice(marks)

    def test_no_absences_rejected(self):
        with self.assertRaises(ProjectError):
            notice([mark(3, "late")])

    def test_empty_marks_rejected(self):
        with self.assertRaises(ProjectError):
            notice([])

if __name__ == "__main__":
    unittest.main()
